-- Delta Prison Life Game Script\n\nlocal Players = game:GetService("Players")\nlocal ReplicatedStorage = game:GetService("ReplicatedStorage")\n\n-- Game settings\nlocal gameSettings = {\n    prisonSize = Vector3.new(1000, 100, 1000),\n    prisonPosition = Vector3.new(0, 0, 0),\n    prisonColor = Color3.fromRGB(100, 100, 100),\n    prisonMaterial = Enum.Material.Concrete,\n    prisonName = "Delta Prison",\n    maxPlayers = 10,\n    respawnTime = 10,\n    initialMoney = 500\n}\n\n-- Create prison\nlocal function createPrison()\n    local prison = Instance.new("Part")\n    prison.Name = gameSettings.prisonName\n    prison.Size = gameSettings.prisonSize\n    prison.Position = gameSettings.prisonPosition\n    prison.Color = gameSettings.prisonColor\n    prison.Material = gameSettings.prisonMaterial\n    prison.Anchored = true\n    prison.Parent = workspace\n\n    -- Create prison walls\n    local wallThickness = 10\n    local wallHeight = 50\n\n    local frontWall = Instance.new("Part")\n    frontWall.Name = "FrontWall"\n    frontWall.Size = Vector3.new(gameSettings.prisonSize.X, wallHeight, wallThickness)\n    frontWall.Position = gameSettings.prisonPosition + Vector3.new(0, wallHeight/2, gameSettings.prisonSize.Z/2 - wallThickness/2)\n    frontWall.Color = gameSettings.prisonColor\n    frontWall.Material = gameSettings.prisonMaterial\n    frontWall.Anchored = true\n    frontWall.Parent = workspace\n\n    local backWall = Instance.new("Part")\n    backWall.Name = "BackWall"\n    backWall.Size = Vector3.new(gameSettings.prisonSize.X, wallHeight, wallThickness)\n    backWall.Position = gameSettings.prisonPosition + Vector3.new(0, wallHeight/2, -gameSettings.prisonSize.Z/2 + wallThickness/2)\n    backWall.Color = gameSettings.prisonColor\n    backWall.Material = gameSettings.prisonMaterial\n    backWall.Anchored = true\n    backWall.Parent = workspace\n\n    local leftWall = Instance.new("Part")\n    leftWall.Name = "LeftWall"\n    leftWall.Size = Vector3.new(wallThickness, wallHeight, gameSettings.prisonSize.Z)\n    leftWall.Position = gameSettings.prisonPosition + Vector3.new(-gameSettings.prisonSize.X/2 + wallThickness/2, wallHeight/2, 0)\n    leftWall.Color = gameSettings.prisonColor\n    leftWall.Material = gameSettings.prisonMaterial\n    leftWall.Anchored = true\n    leftWall.Parent = workspace\n\n    local rightWall = Instance.new("Part")\n    rightWall.Name = "RightWall"\n    rightWall.Size = Vector3.new(wallThickness, wallHeight, gameSettings.prisonSize.Z)\n    rightWall.Position = gameSettings.prisonPosition + Vector3.new(gameSettings.prisonSize.X/2 - wallThickness/2, wallHeight/2, 0)\n    rightWall.Color = gameSettings.prisonColor\n    rightWall.Material = gameSettings.prisonMaterial\n    rightWall.Anchored = true\n    rightWall.Parent = workspace\n\n    -- Create prison floor\n    local floor = Instance.new("Part")\n    floor.Name = "Floor"\n    floor.Size = Vector3.new(gameSettings.prisonSize.X, 1, gameSettings.prisonSize.Z)\n    floor.Position = gameSettings.prisonPosition + Vector3.new(0, -0.5, 0)\n    floor.Color = gameSettings.prisonColor\n    floor.Material = gameSettings.prisonMaterial\n    floor.Anchored = true\n    floor.Parent = workspace\n\n    -- Create prison roof\n    local roof = Instance.new("Part")\n    roof.Name = "Roof"\n    roof.Size = Vector3.new(gameSettings.prisonSize.X, 1, gameSettings.prisonSize.Z)\n    roof.Position = gameSettings.prisonPosition + Vector3.new(0, gameSettings.prisonSize.Y/2 - 0.5, 0)\n    roof.Color = gameSettings.prisonColor\n    roof.Material = gameSettings.prisonMaterial\n    roof.Anchored = true\n    roof.Parent = workspace\nend\n\n-- Player join handler\nlocal function onPlayerAdded(player)\n    -- Create character\n    local character = Instance.new("Model")\n    character.Name = player.Name\n    character.Parent = workspace\n\n    -- Create head\n    local head = Instance.new("Part")\n    head.Name = "Head"\n    head.Size = Vector3.new(2, 1, 1)\n    head.Position = Vector3.new(0, 5, 0)\n    head.Anchored = true\n    head.Parent = character\n\n    -- Create torso\n    local torso = Instance.new("Part")\n    torso.Name = "Torso"\n    torso.Size = Vector3.new(2, 2, 1)\n    torso.Position = Vector3.new(0, 3, 0)\n    torso.Anchored = true\n    torso.Parent = character\n\n    -- Create left arm\n    local leftArm = Instance.new("Part")\n    leftArm.Name = "Left Arm"\n    leftArm.Size = Vector3.new(1, 2, 1)\n    leftArm.Position = Vector3.new(-1.5, 3, 0)\n    leftArm.Anchored = true\n    leftArm.Parent = character\n\n    -- Create right arm\n    local rightArm = Instance.new("Part")\n    rightArm.Name = "Right Arm"\n    rightArm.Size = Vector3.new(1, 2, 1)\n    rightArm.Position = Vector3.new(1.5, 3, 0)\n    rightArm.Anchored = true\n    rightArm.Parent = character\n\n    -- Create left leg\n    local leftLeg = Instance.new("Part")\n    leftLeg.Name = "Left Leg"\n    leftLeg.Size = Vector3.new(1, 2, 1)\n    leftLeg.Position = Vector3.new(-0.5, 1, 0)\n    leftLeg.Anchored = true\n    leftLeg.Parent = character\n\n    -- Create right leg\n    local rightLeg = Instance.new("Part")\n    rightLeg.Name = "Right Leg"\n    rightLeg.Size = Vector3.new(1, 2, 1)\n    rightLeg.Position = Vector3.new(0.5, 1, 0)\n    rightLeg.Anchored = true\n    rightLeg.Parent = character\n\n    -- Create humanoid\n    local humanoid = Instance.new("Humanoid")\n    humanoid.Name = "Humanoid"\n    humanoid.Parent = character\n\n    -- Set character to player\n    player.Character = character\n\n    -- Initialize player money\n    local leaderstats = Instance.new("Folder")\n    leaderstats.Name = "leaderstats"\n    leaderstats.Parent = player\n\n    local money = Instance.new("IntValue")\n    money.Name = "Money"\n    money.Value = gameSettings.initialMoney\n    money.Parent = leaderstats\nend\n\n-- Initialize game\ncreatePrison()\nPlayers.PlayerAdded:Connect(onPlayerAdded)\